fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        return (a, Vec::new());
    }

    let mid = n / 2; // ensures 1 <= mid < n when n > 1
    let mut a = a;
    let right = a.split_off(mid); // a becomes left part, right is remaining
    (a, right)
}